const CACHE = `cc-${PRECACHE.version}`;
// Never served from cache: runtime config written at deploy time.
const NETWORK_FIRST = new Set(['config.js']);

self.addEventListener('install', (e) => {
  // cache: 'reload' bypasses the HTTP cache (GitHub Pages lets browsers keep files for 10 minutes),
  // so a new version never gets stored with stale copies of its files.
  e.waitUntil(caches.open(CACHE).then((c) => c.addAll(['./', ...PRECACHE.files].map((u) => new Request(u, { cache: 'reload' })))));
});

self.addEventListener('activate', (e) => {
  e.waitUntil(caches.keys()
    .then((keys) => Promise.all(keys.filter((k) => k.startsWith('cc-') && k !== CACHE).map((k) => caches.delete(k))))
    .then(() => self.clients.claim()));
});

self.addEventListener('message', (e) => { if (e.data === 'skip-waiting') self.skipWaiting(); });

self.addEventListener('fetch', (e) => {
  const url = new URL(e.request.url);
  if (e.request.method !== 'GET' || url.origin !== self.location.origin) return; // API calls go straight to the network
  const scope = new URL(self.registration.scope);
  const rel = url.pathname.startsWith(scope.pathname) ? url.pathname.slice(scope.pathname.length) : null;
  if (rel === null) return;

  if (NETWORK_FIRST.has(rel)) {
    e.respondWith(fetch(e.request).then((res) => {
      if (res.ok) { const copy = res.clone(); caches.open(CACHE).then((c) => c.put(e.request, copy)); }
      return res;
    }).catch(() => caches.match(e.request)));
    return;
  }
  // Cache first (precached files are versioned as a set), network as a fallback.
  e.respondWith(caches.match(e.request, { ignoreSearch: true }).then((hit) => hit || fetch(e.request).catch(() => {
    if (e.request.mode === 'navigate') return caches.match('./');
    return Response.error();
  })));
});
